module tb;
  reg clk=0, rst_n=0, data=0;
  wire match, not_match;
  TopModule dut(.clk(clk), .rst_n(rst_n), .data(data), .match(match), .not_match(not_match));

  always #5 clk = ~clk;

  task send_bit(input bit b);
    begin
      @(negedge clk);
      data = b;
      @(posedge clk);
      #1;
      "'$display("t=%0t data=%0b pstate=%0d nstate=%0d match=%0b not_match=%0b", $time, b, dut.pstate, dut.nstate, match, not_match);
    end
  endtask

  initial begin
    data = 0;
    rst_n = 0;
    repeat (2) @(negedge clk);
    rst_n = 1;

    // Exact match: 011100
    send_bit(0); send_bit(1); send_bit(1); send_bit(1); send_bit(0); send_bit(0);

    // First bit mismatch: 100000 -> should assert not_match at group end
    send_bit(1); send_bit(0); send_bit(0); send_bit(0); send_bit(0); send_bit(0);

    // Mid-group mismatch: 011101 -> should assert not_match at group end
    send_bit(0); send_bit(1); send_bit(1); send_bit(1); send_bit(0); send_bit(1);

    $finish;
  end
endmodule
EOF
